<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap/app.php';require_role('ADMIN');$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$sql="SELECT m.MemberNumber,m.FirstName,m.LastName,m.Phone,m.JoinedOn,m.Status,u.Email,u.Status AccountStatus,ms.PlanNameSnapshot,ms.Status MembershipStatus,ms.EndsOn FROM MEMBER m JOIN USER_ACCOUNT u ON u.UserAccountID=m.UserAccountID LEFT JOIN MEMBERSHIP ms ON ms.MembershipID=(SELECT x.MembershipID FROM MEMBERSHIP x WHERE x.MemberID=m.MemberID ORDER BY x.MembershipID DESC LIMIT 1) WHERE 1=1";$types='';$params=[];if($q!==''){$sql.=" AND (m.MemberNumber LIKE CONCAT('%',?,'%') OR m.FirstName LIKE CONCAT('%',?,'%') OR m.LastName LIKE CONCAT('%',?,'%') OR u.Email LIKE CONCAT('%',?,'%'))";$types.='ssss';array_push($params,$q,$q,$q,$q);}if(in_array($status,['ACTIVE','INACTIVE','SUSPENDED','ARCHIVED'],true)){$sql.=' AND m.Status=?';$types.='s';$params[]=$status;}$sql.=' ORDER BY m.LastName,m.FirstName LIMIT 500';$rows=db_all($sql,$types,$params);$pageTitle='Members';$pageSubtitle='Member directory and membership status';include V2_ROOT.'/includes/header.php';?>
<form method="get" class="filter-bar"><label>Search<input name="q" value="<?=e($q)?>"></label><label>Status<select name="status"><option value="">All</option><?php foreach(['ACTIVE','INACTIVE','SUSPENDED','ARCHIVED'] as $item):?><option <?=$status===$item?'selected':''?>><?=$item?></option><?php endforeach;?></select></label><button>Filter</button></form><div class="table-wrap"><table><thead><tr><th>Member</th><th>Contact</th><th>Account</th><th>Membership</th><th>Joined</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['FirstName'].' '.$row['LastName'])?><br><small><?=e($row['MemberNumber'])?> · <?=e($row['Status'])?></small></td><td><?=e($row['Email'])?><br><small><?=e($row['Phone']??'')?></small></td><td><?=e($row['AccountStatus'])?></td><td><?=e($row['PlanNameSnapshot']??'None')?> · <?=e($row['MembershipStatus']??'NONE')?><br><small><?=e($row['EndsOn']??'')?></small></td><td><?=e($row['JoinedOn'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">No members found.</td></tr><?php endif;?></tbody></table></div><?php include V2_ROOT.'/includes/footer.php';?>
